//! Embeds Kiku's icon (regenerated by `scripts/make-icon.py`) and its version info in `kiku.exe`: the
//! product's name only, never a person's.

fn main() {
    println!("cargo:rerun-if-changed=../../assets/icon/kiku.ico");
    winresource::WindowsResource::new()
        .set_icon("../../assets/icon/kiku.ico")
        .set("FileDescription", "Kiku")
        .set("ProductName", "Kiku")
        .set("CompanyName", "Kiku")
        .set("LegalCopyright", "Copyright (c) 2026 Kiku contributors. MIT License.")
        .set("OriginalFilename", "kiku.exe")
        .set("InternalName", "kiku")
        .compile()
        .expect("embedding the icon needs the Windows SDK's rc.exe");
}
